# Generated by Gemini 4 Hydrogen
import csv
from pathlib import Path

INPUT_FILES = ["bom.csv", "bom_extras.csv"]
OUTPUT_FILE = "bom_merged.csv"
TARGET_COLUMNS = ["Qty", "MPN", "Mouser"]


def merge_boms(input_paths, output_path):
    merged_rows = {}  # Keyed by (MPN, Mouser) to combine duplicate line items

    for file_path in input_paths:
        path = Path(file_path)
        if not path.exists():
            print(f"Warning: {file_path} not found, skipping.")
            continue

        with path.open(mode="r", encoding="utf-8-sig", newline="") as f:
            reader = csv.DictReader(f)
            # Strip accidental whitespace around header names
            reader.fieldnames = [h.strip() for h in (reader.fieldnames or [])]

            missing = [col for col in TARGET_COLUMNS if col not in reader.fieldnames]
            if missing:
                raise ValueError(f"{file_path} is missing required columns: {missing}")

            for row in reader:
                mpn = (row.get("MPN") or "").strip()
                mouser = (row.get("Mouser") or "").strip()
                qty_raw = (row.get("Qty") or "").strip()

                # Skip completely empty rows
                if not mpn and not mouser and not qty_raw:
                    continue

                try:
                    qty = int(float(qty_raw)) if qty_raw else 0
                except ValueError:
                    raise ValueError(f"Invalid Qty '{qty_raw}' for MPN '{mpn}' in {file_path}")

                key = (mpn, mouser)
                merged_rows[key] = merged_rows.get(key, 0) + qty

    with open(output_path, mode="w", encoding="utf-8", newline="") as out_f:
        writer = csv.DictWriter(out_f, fieldnames=TARGET_COLUMNS)
        writer.writeheader()
        for (mpn, mouser), total_qty in merged_rows.items():
            writer.writerow({
                "Qty": total_qty,
                "MPN": mpn,
                "Mouser": mouser,
            })

    print(f"Merged {len(merged_rows)} unique parts into '{output_path}'.")


if __name__ == "__main__":
    merge_boms(INPUT_FILES, OUTPUT_FILE)
